  id uuid primary key,
  sync_seq bigint not null default 0,
  server_updated_at timestamptz not null default now()
);
alter table public.notes add column if not exists division text not null default 'crops';
alter table public.notes add column if not exists kind text not null default 'note';
alter table public.notes add column if not exists body text not null default '';
alter table public.notes add column if not exists amount numeric not null default 0;
alter table public.notes add column if not exists person text;
alter table public.notes add column if not exists due_date date;
alter table public.notes add column if not exists done boolean not null default false;
alter table public.notes add column if not exists done_by text;
alter table public.notes add column if not exists done_at timestamptz;
alter table public.notes add column if not exists pinned boolean not null default false;
alter table public.notes add column if not exists created_at timestamptz;
alter table public.notes add column if not exists updated_at timestamptz;
alter table public.notes add column if not exists deleted boolean not null default false;
alter table public.notes add column if not exists created_by_name text;
alter table public.notes add column if not exists updated_by_name text;
create index if not exists notes_sync_seq_idx on public.notes (sync_seq);
create index if not exists notes_division_idx on public.notes (division, sync_seq);
drop trigger if exists notes_sync on public.notes;
create trigger notes_sync before insert or update on public.notes for each row execute function public.tg_sync_row();
alter table public.notes enable row level security;
grant select, insert, update on public.notes to anon, authenticated;
drop policy if exists notes_select on public.notes;
create policy notes_select on public.notes for select to anon, authenticated using ((select public.erp_session_division()) = 'all' or division = (select public.erp_session_division()) or (division = 'all' and (select public.erp_session_division()) is not null));
drop policy if exists notes_insert on public.notes;
create policy notes_insert on public.notes for insert to anon, authenticated with check ((select public.erp_session_division()) = 'all' or division = (select public.erp_session_division()) or (division = 'all' and (select public.erp_session_division()) is not null));
drop policy if exists notes_update on public.notes;
create policy notes_update on public.notes for update to anon, authenticated using ((select public.erp_session_division()) = 'all' or division = (select public.erp_session_division()) or (division = 'all' and (select public.erp_session_division()) is not null)) with check ((select public.erp_session_division()) = 'all' or division = (select public.erp_session_division()) or (division = 'all' and (select public.erp_session_division()) is not null));

-- Version 1 functions, no longer referenced by any policy.
drop function if exists public.register_device(uuid, text);
drop function if exists public.is_active_member();
drop function if exists public.is_admin();

